#include <bits/stdc++.h>
#include <chrono>
using namespace std; using namespace std::chrono;
static constexpr double GRID=1.0, RT_COMM=0.07, DAILY_TARGET=10.0;
struct B{bool a=false;double z=0;int buys=0,sells=0,mp=0,mn=0,orders=0,flips=0,lastAddSide=0,maxOpen=0,maxBalanced=0,maxSpan=0;double bs=0,ss=0,minLiq=0,maxSpread=0,h1Range=0;long long startT=0,endT=0;int startDate=0;int firstSide=0;};
struct S{double bal=1000000,dayReal=0;bool stop=false;B b;long long hk=LLONG_MIN,lastT=0;double hh=-1e100,hl=1e100,lastH=0,lastL=0;bool lastHV=false;double rH=0,rL=0;bool rV=false,armed=false,needIn=false;double lb=0,la=0;int curDate=0;};
bool parse(const string&l,int&date,int&sec,double&bid,double&ask){if(l.empty()||l[0]!='\"'||l.rfind("\"Exness\"",0)==0)return false;size_t c1=l.find(','),c2=l.find(',',c1+1),c3=l.find(',',c2+1),c4=l.find(',',c3+1);if(c4==string::npos)return false;string t=l.substr(c2+1,c3-c2-1);if(!t.empty()&&t.front()=='\"')t.erase(t.begin());if(!t.empty()&&t.back()=='\"')t.pop_back();if(t.size()<19)return false;date=stoi(t.substr(0,4))*10000+stoi(t.substr(5,2))*100+stoi(t.substr(8,2));sec=stoi(t.substr(11,2))*3600+stoi(t.substr(14,2))*60+stoi(t.substr(17,2));bid=strtod(l.c_str()+c3+1,nullptr);ask=strtod(l.c_str()+c4+1,nullptr);return bid>0&&ask>=bid;}
long long epochDay(int date){int y=date/10000,m=(date/100)%100,d=date%100;sys_days sd=year{y}/month{(unsigned)m}/day{(unsigned)d};return duration_cast<days>(sd.time_since_epoch()).count();}
int wd(int date){int y=date/10000,m=(date/100)%100,d=date%100;weekday w{sys_days{year{y}/month{(unsigned)m}/day{(unsigned)d}}};return w.c_encoding();}
inline double liq(const B&b,double bid,double ask){return !b.a?0:b.buys*bid-b.bs+b.ss-b.sells*ask-RT_COMM*(b.buys+b.sells);} 
void setR(S&s,bool need){if(s.lastHV){s.rH=s.lastH;s.rL=s.lastL;s.rV=true;s.needIn=need;s.armed=!need;}}
void updB(B&b,double bid,double ask){if(!b.a)return;double q=liq(b,bid,ask);b.minLiq=min(b.minLiq,q);b.maxSpread=max(b.maxSpread,ask-bid);b.maxOpen=max(b.maxOpen,b.buys+b.sells);b.maxBalanced=max(b.maxBalanced,min(b.mp,-b.mn));b.maxSpan=max(b.maxSpan,b.mp-b.mn);}
void emit(const B&b,double pnl,const string&reason){double dur=(b.endT-b.startT)/3600.0;cout<<b.startDate<<","<<b.firstSide<<","<<fixed<<setprecision(6)<<b.h1Range<<","<<b.orders<<","<<b.maxOpen<<","<<b.mp<<","<<b.mn<<","<<b.maxBalanced<<","<<b.maxSpan<<","<<b.flips<<","<<dur<<","<<b.minLiq<<","<<b.maxSpread<<","<<pnl<<","<<reason<<"\n";}
void closeB(S&s,double bid,double ask,const string&r,long long t){double q=liq(s.b,bid,ask);s.b.endT=t;emit(s.b,q,r);s.bal+=q;s.dayReal+=q;s.b=B();setR(s,true);if(s.dayReal>=DAILY_TARGET-1e-12)s.stop=true;}
void startB(S&s,int side,double bid,double ask,long long t){s.b=B();auto&b=s.b;b.a=true;b.z=bid;b.startT=t;b.startDate=s.curDate;b.firstSide=side;b.h1Range=s.rH-s.rL;b.orders=1;b.lastAddSide=side;double f=side==1?ask:bid;if(side==1){b.buys=1;b.bs=f;}else{b.sells=1;b.ss=f;}b.minLiq=liq(b,bid,ask);updB(b,bid,ask);s.armed=false;}
void add(S&s,int side,double bid,double ask){auto&b=s.b;if(b.lastAddSide&&b.lastAddSide!=side)b.flips++;b.lastAddSide=side;b.orders++;double f=side==1?ask:bid;if(side==1){b.buys++;b.bs+=f;}else{b.sells++;b.ss+=f;}updB(b,bid,ask);}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);cout<<"start_date,first_side,h1_range,orders,max_open,max_pos,min_neg,max_balanced,max_span,side_flips,duration_h,min_liq,max_spread,close_pnl,reason\n";S s;string line;bool init=false;while(getline(cin,line)){int date,sec;double bid,ask;if(!parse(line,date,sec,bid,ask))continue;long long t=epochDay(date)*86400+sec;if(!init){s.curDate=date;init=true;}if(date!=s.curDate){if(wd(s.curDate)==5&&s.b.a)closeB(s,s.lb,s.la,"friday",s.lastT);s.curDate=date;s.dayReal=0;s.stop=false;}s.lb=bid;s.la=ask;s.lastT=t;long long hk=epochDay(date)*24+sec/3600;if(s.hk==LLONG_MIN){s.hk=hk;s.hh=s.hl=bid;continue;}if(hk!=s.hk){s.lastH=s.hh;s.lastL=s.hl;s.lastHV=s.hh>s.hl;if(!s.b.a&&!s.stop&&wd(date)>=1&&wd(date)<=5)setR(s,false);s.hk=hk;s.hh=s.hl=bid;}else{s.hh=max(s.hh,bid);s.hl=min(s.hl,bid);}updB(s.b,bid,ask);int w=wd(date);if(w==0||w==6||s.stop)continue;if(!s.b.a){if(!s.rV)continue;if(s.needIn){if(bid<=s.rH&&bid>=s.rL){s.needIn=false;s.armed=true;}else continue;}if(!s.armed)continue;if(bid>s.rH)startB(s,1,bid,ask,t);else if(bid<s.rL)startB(s,-1,bid,ask,t);continue;}double q=liq(s.b,bid,ask);if(s.dayReal+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,"daily_target",t);continue;}bool cp=bid>=s.b.z+(s.b.mp+1)*GRID,cn=bid<=s.b.z+(s.b.mn-1)*GRID;if(cp){while(s.b.a&&bid>=s.b.z+(s.b.mp+1)*GRID){q=liq(s.b,bid,ask);if(q>0){closeB(s,bid,ask,"cycle_profit",t);break;}s.b.mp++;add(s,1,bid,ask);q=liq(s.b,bid,ask);if(s.dayReal+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,"daily_target",t);break;}}}else if(cn){while(s.b.a&&bid<=s.b.z+(s.b.mn-1)*GRID){q=liq(s.b,bid,ask);if(q>0){closeB(s,bid,ask,"cycle_profit",t);break;}s.b.mn--;add(s,-1,bid,ask);q=liq(s.b,bid,ask);if(s.dayReal+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,"daily_target",t);break;}}}}
return 0;}
